import React, { useState, useRef, useEffect } from 'react';
import { useCombatActions } from '../../actions/combatActions';
import { GameState } from '../../types/game';
import { selfId } from 'trystero';
import type { Room } from 'trystero/nostr';
import { imageManager } from '../../services/ImageManager';
import { Star } from 'lucide-react';

interface BattleMapProps {
  gameState: GameState;
  onGameStateChange: (newState: GameState) => void;
  room?: Room;
  isRoomCreator: boolean;
}

interface Position {
  x: number;
  y: number;
}

const BattleMap: React.FC<BattleMapProps> = ({
  gameState,
  onGameStateChange,
  room,
  isRoomCreator
}) => {
  // Container ref for measuring
  const containerRef = useRef<HTMLDivElement>(null);
  const [containerSize, setContainerSize] = useState({ width: 0, height: 0 });

  // Grid constants
  const GRID_SIZE = { width: 63, height: 63 };

  // State for drag operations
  const [draggedActorId, setDraggedActorId] = useState<string | null>(null);
  const [dragPosition, setDragPosition] = useState<Position | null>(null);
  const [hoveredActorId, setHoveredActorId] = useState<string | null>(null);

  // State for loaded images
  const [imageUrls, setImageUrls] = useState<{ [key: string]: string }>({});

  // Combat actions for state updates
  const combatActions = useCombatActions(room, gameState, onGameStateChange, isRoomCreator);

  // Calculate cell dimensions based on container size
  const cellWidth = containerSize.width / GRID_SIZE.width;
  const cellHeight = containerSize.height / GRID_SIZE.height;

  // Get all actors (characters and field entities)
  const actors = [
    ...gameState.party.map(char => ({ ...char, type: 'character' as const })),
    ...gameState.field.map(entity => ({ ...entity, type: 'entity' as const }))
  ];

  // Load images when actors change or new pieces are added
  useEffect(() => {
    let mounted = true;
    const createdUrls: string[] = [];  // Track URLs created in this effect

    const loadActorImages = async () => {
      const newImageUrls: { [key: string]: string } = {};
      const loadPromises = actors.map(async (actor) => {
        if (!actor.image) return;

        // Check if we already have a URL for this image
        if (imageUrls[actor.id]) return;

        try {
          // Try to get thumbnail first for quick loading
          const thumbnail = imageManager.getThumbnail(actor.image);
          if (thumbnail && mounted) {
            newImageUrls[actor.id] = thumbnail;
          }

          // Then load full image
          const imageFile = await imageManager.getImage(actor.image);
          if (imageFile && mounted) {
            const url = URL.createObjectURL(imageFile);
            newImageUrls[actor.id] = url;
            createdUrls.push(url);  // Track the created URL
          }
        } catch (error) {
          console.error('Failed to load actor image:', error);
        }
      });

      await Promise.all(loadPromises);
      
      if (mounted) {
        setImageUrls(prev => ({
          ...prev,
          ...newImageUrls
        }));
      }
    };

    loadActorImages();
    
    return () => {
      mounted = false;
      // Cleanup only the URLs created in this effect
      createdUrls.forEach(url => {
        URL.revokeObjectURL(url);
      });
    };
  }, [actors.map(a => a.id + a.image).join(',')]);

  // Watch for new actors and initialize their positions
  useEffect(() => {
    if (!gameState.combat?.isActive || !combatActions) return;

    const positionedActorIds = Object.keys(gameState.combat.positions || {});

    // Find actors without positions
    const unpositionedActors = actors.filter(
      actor => !positionedActorIds.includes(actor.id)
    );

    // Initialize positions for new actors
    if (isRoomCreator) {
      unpositionedActors.forEach(actor => {
        combatActions.initializePosition(actor.id, actor.type === 'character');
      });
    }
  }, [actors, gameState.combat?.isActive, combatActions, isRoomCreator]);

  // Update container size on resize
  useEffect(() => {
    if (!containerRef.current) return;

    const updateSize = () => {
      const container = containerRef.current;
      if (!container) return;

      const rect = container.getBoundingClientRect();
      setContainerSize({
        width: rect.width,
        height: rect.height
      });
    };

    updateSize();

    const resizeObserver = new ResizeObserver(updateSize);
    resizeObserver.observe(containerRef.current);

    return () => {
      if (containerRef.current) {
        resizeObserver.unobserve(containerRef.current);
      }
    };
  }, []);

  // Check if user can move a piece
  const canMovePiece = (actorId: string) => {
    if (isRoomCreator) return true;
    const character = gameState.party.find(c => c.id === actorId);
    return character?.playerId === selfId;
  };

  // Handle mouse events
  const handleMouseDown = (actorId: string, e: React.MouseEvent) => {
    if (!canMovePiece(actorId) || !gameState.combat?.positions) return;

    e.preventDefault();
    const currentPos = gameState.combat.positions[actorId];
    if (currentPos) {
      setDragPosition({
        x: currentPos.x * cellWidth + cellWidth / 2,
        y: currentPos.y * cellHeight + cellHeight / 2
      });
    }
    setDraggedActorId(actorId);
    setHoveredActorId(null);
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!draggedActorId || !containerRef.current) return;

    const rect = containerRef.current.getBoundingClientRect();
    const x = Math.max(0, Math.min(e.clientX - rect.left, containerSize.width));
    const y = Math.max(0, Math.min(e.clientY - rect.top, containerSize.height));

    setDragPosition({ x, y });
  };

  const handleMouseUp = (e: React.MouseEvent) => {
    if (!draggedActorId || !containerRef.current || !gameState.combat?.positions) return;

    const rect = containerRef.current.getBoundingClientRect();
    const x = Math.floor((e.clientX - rect.left) / cellWidth);
    const y = Math.floor((e.clientY - rect.top) / cellHeight);

    const newX = Math.max(0, Math.min(x, GRID_SIZE.width - 1));
    const newY = Math.max(0, Math.min(y, GRID_SIZE.height - 1));

    // Check if position is taken
    const isTaken = Object.entries(gameState.combat.positions || {})
      .some(([id, pos]) => id !== draggedActorId && pos.x === newX && pos.y === newY);

    if (!isTaken) {
      const position = {
        x: newX,
        y: newY
      };

      if (isRoomCreator) {
        combatActions.movePiece(draggedActorId, position);
      } else {
        combatActions.requestMove(draggedActorId, position);
      }
    }

    setDragPosition(null);
    setDraggedActorId(null);
  };

  const handleMouseLeave = () => {
    setDragPosition(null);
    setDraggedActorId(null);
    setHoveredActorId(null);
  };

  // Get pixel position for an actor
  const getPixelPosition = (actorId: string) => {
    if (draggedActorId === actorId && dragPosition) {
      return dragPosition;
    }

    const pos = gameState.combat?.positions?.[actorId];
    if (!pos) return null;

    return {
      x: pos.x * cellWidth + cellWidth / 2,
      y: pos.y * cellHeight + cellHeight / 2
    };
  };

  // Piece size
  const pieceRadius = Math.min(cellWidth, cellHeight) * 3;

  return (
    <div 
      ref={containerRef} 
      className="overflow-hidden rounded-lg w-full h-full relative bg-transparent border-2 border-grey dark:border-offwhite"
      onMouseMove={handleMouseMove}
      onMouseUp={handleMouseUp}
      onMouseLeave={handleMouseLeave}
    >
      {/* Turn indicator */}
      {gameState.combat?.isActive && (
        <div className={`
          absolute top-4 left-4 px-4 py-1 z-10 rounded-lg xl:text-xs 2xl:text-md 3xl:text-xl font-['BrunoAceSC']
          ${gameState.combat.initiativeSide === 'party' 
            ? 'bg-blue dark:bg-cyan text-white dark:text-grey'
            : 'bg-purple dark:bg-pink text-white dark:text-grey'}
        `}>
          Turn {gameState.combat.currentTurn}
        </div>
      )}

      {containerSize.width > 0 && containerSize.height > 0 && (
        <svg 
          width={containerSize.width} 
          height={containerSize.height} 
          className="absolute inset-0"
        >
          {/* Base circles pattern */}
          {(() => {
            const centerX = containerSize.width / 2;
            const centerY = containerSize.height / 2;
            const maxRadius = Math.min(containerSize.width, containerSize.height) * 1.5;
            const numCircles = 6;

            return (
              <g>
                {Array.from({ length: numCircles }).map((_, i) => {
                  const radius = (maxRadius * (i + 1)) / numCircles;
                  return (
                    <circle
                      key={`circle-${i}`}
                      cx={centerX}
                      cy={centerY}
                      r={radius}
                      fill="none"
                      stroke="currentColor"
                      strokeOpacity={0.15}
                      strokeWidth={2}
                    />
                  );
                })}
              </g>
            );
          })()}
            <path
            d="M0,-13 L3,-3 13,0 3,3 0,13 -3,3 -13,0 -3,-3Z"
            transform={`translate(${containerSize.width / 2} ${containerSize.height / 2})`}
            className="fill-current opacity-50"
          />
          {/* Movement arrows */}
          {gameState.combat && Object.entries(gameState.combat.positions || {}).map(([actorId, pos]) => {
            if (!pos.lastMoveFrom) return null;

            const startX = pos.lastMoveFrom.x * cellWidth + cellWidth / 2;
            const startY = pos.lastMoveFrom.y * cellHeight + cellHeight / 2;
            const endX = pos.x * cellWidth + cellWidth / 2;
            const endY = pos.y * cellHeight + cellHeight / 2;

            // Calculate arrow parameters - adjusted for larger pieces
            const angle = Math.atan2(endY - startY, endX - startX);
            const arrowLength = pieceRadius * 0.4;  // Scale arrow with piece size
            const arrowAngle = Math.PI / 6;
            const backoff = pieceRadius + 4;  // Move arrow back by piece radius plus a small gap

            // Adjust end point to be outside the circle
            const adjustedEndX = endX - backoff * Math.cos(angle);
            const adjustedEndY = endY - backoff * Math.sin(angle);

            // Calculate arrow points from the adjusted end
            const point1X = adjustedEndX - arrowLength * Math.cos(angle - arrowAngle);
            const point1Y = adjustedEndY - arrowLength * Math.sin(angle - arrowAngle);
            const point2X = adjustedEndX - arrowLength * Math.cos(angle + arrowAngle);
            const point2Y = adjustedEndY - arrowLength * Math.sin(angle + arrowAngle);

            return (
              <g key={`arrow-${actorId}`} className="opacity-50">
                <line
                  x1={startX}
                  y1={startY}
                  x2={adjustedEndX}
                  y2={adjustedEndY}
                  stroke="currentColor"
                  strokeWidth={2}
                />
                <line
                  x1={point1X}
                  y1={point1Y}
                  x2={adjustedEndX}
                  y2={adjustedEndY}
                  stroke="currentColor"
                  strokeWidth={2}
                />
                <line
                  x1={point2X}
                  y1={point2Y}
                  x2={adjustedEndX}
                  y2={adjustedEndY}
                  stroke="currentColor"
                  strokeWidth={2}
                />
              </g>
            );
          })}

          {/* Actor pieces */}
          {actors.map(actor => {
            const pixelPos = getPixelPosition(actor.id);
            if (!pixelPos) return null;

            return (
              <g key={actor.id}>
                {/* Pattern definition */}
                <defs>
                  <pattern
                    id={`actor-pattern-${actor.id}`}
                    width="1"
                    height="1"
                    patternUnits="objectBoundingBox"
                    patternContentUnits="objectBoundingBox"
                  >
                    <image
                      href={imageUrls[actor.id] || '/api/placeholder/400/400'}
                      width="1"
                      height="1"
                      preserveAspectRatio="xMidYMid slice"
                    />
                  </pattern>
                </defs>

                {/* Background circle for border */}
                <circle
                  cx={pixelPos.x}
                  cy={pixelPos.y}
                  r={pieceRadius + 2}
                  className={`
                    fill-grey
                    dark:fill-offwhite
                    
                    ${canMovePiece(actor.id) ? 'cursor-grab' : 'cursor-not-allowed'}
                    ${draggedActorId === actor.id ? 'cursor-grabbing' : ''}
                  `}
                  style={{
                    transition: draggedActorId === actor.id ? 'none' : 'all 0.3s ease-out'
                  }}
                />

                {/* Main image circle */}
                <circle
                  cx={pixelPos.x}
                  cy={pixelPos.y}
                  r={pieceRadius}
                  fill={`url(#actor-pattern-${actor.id})`}
                  style={{
                    transition: draggedActorId === actor.id ? 'none' : 'all 0.3s ease-out'
                  }}
                  onMouseDown={(e) => handleMouseDown(actor.id, e)}
                  onMouseEnter={() => !draggedActorId && setHoveredActorId(actor.id)}
                  onMouseLeave={() => !draggedActorId && setHoveredActorId(null)}
                />
                

                {/* Name tooltip */}
                {hoveredActorId === actor.id && (
                  <foreignObject
                    x={pixelPos.x - 60}
                    y={pixelPos.y - pieceRadius - 30}
                    width="120"
                    height="25"
                  >
                    <div className="bg-black/50 dark:bg-white/50 text-white dark:text-black px-2 py-1 rounded text-sm text-center">
                      {actor.name}
                    </div>
                  </foreignObject>
                )}
              </g>
            );
          })}
        </svg>
      )}
    </div>
  );
};

export default BattleMap;